style.css:
@-moz-document domain("roblox.com") {
/* === BACKGROUND IMAGE === */
  body {
    background-image: url("https://imgur.com/a/i5vg2gW.jpg"); /* Replace with your hosted image */
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  /* === TRANSLUCENT PANELS === */
  .content, .section, .container-main, .game-card-container, .rbx-header, .rbx-navbar, .modal-content {
    background-color: rgba(255, 245, 250, 0.85) !important;
    backdrop-filter: blur(6px);
    border-radius: 12px;
  }

  /* === TEXT COLORS === */
  body,
  h1, h2, h3, h4, h5, h6,
  .text, .text-label, .game-card-name, .section-title {
    color: #7a004d !important;
  }

  a, .text-link, .rbx-tab, .rbx-tab:hover {
    color: #cc3366 !important;
  }

  /* === BUTTONS === */
  .btn-primary,
  .btn-secondary,
  .btn-control-sm,
  .btn-control-md,
  .btn-growth-md,
  .btn-growth-lg {
    background-color: #ff66b3 !important;
    border-color: #ff3385 !important;
    color: white !important;
    border-radius: 8px;
  }

  .btn-primary:hover,
  .btn-secondary:hover {
    background-color: #ff3385 !important;
    border-color: #cc0052 !important;
  }

  /* === NAVIGATION BAR === */
  .rbx-header, .rbx-navbar {
    background-color: rgba(255, 204, 229, 0.9) !important;
    border-bottom: 2px solid #ff99cc !important;
  }

  /* === GAME CARD STYLING === */
  .game-card-container {
    border: 1px solid #ffb3d9 !important;
    box-shadow: 0 4px 12px rgba(255, 153, 204, 0.3) !important;
  }

  /* === SCROLLBAR === */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #ffe6f0;
  }

  ::-webkit-scrollbar-thumb {
    background: #ff66b3;
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #ff3385;
  }
}
